            return list(itertools.permutations(self.datas, m))

    def select_all(self):
        return list(itertools.product(self.datas, repeat=len(self.datas)))

    @staticmethod
    def factorial(n):
        if n == 0:
            return 1
        return n * ArrangementCalculator.factorial(n - 1)
