    def clean_non_binary_chars(self):
        self.binary_string = ''.join((v0 for v0 in self.binary_string if v0 in '01'))

    def calculate_binary_info(self):
        v0 = self.binary_string.count('0')
        v1 = self.binary_string.count('1')
        v2 = len(self.binary_string)
        v3 = v0 / v2 * 100
        v4 = v1 / v2 * 100
        return {'Zeroes': v3, 'Ones': v4, 'Bit length': v2}

    def convert_to_ascii(self):
        return ''.join((chr(int(self.binary_string[v0:v0 + 8], 2)) for v0 in range(0, len(self.binary_string), 8)))

    def convert_to_utf8(self):
        return ''.join((chr(int(self.binary_string[v0:v0 + 6], 2)) for v0 in range(0, len(self.binary_string), 6)))
