        for course in self.courses:
            start_time_obj = datetime.strptime(course['start_time'], '%H:%M')
            end_time_obj = datetime.strptime(course['end_time'], '%H:%M')
            if start_time_obj <= check_time_obj <= end_time_obj:
                return False
        return True

    def check_course_conflict(self, new_course):
        new_start_time_obj = datetime.strptime(new_course['start_time'], '%H:%M')
        new_end_time_obj = datetime.strptime(new_course['end_time'], '%H:%M')
        for course in self.courses:
            start_time_obj = datetime.strptime(course['start_time'], '%H:%M')
            end_time_obj = datetime.strptime(course['end_time'], '%H:%M')
            # Check for conflicts at the boundary
            if start_time_obj <= new_end_time_obj and new_start_time_obj <= end_time_obj:
                return False
            if start_time_obj < new_start_time_obj and new_end_time_obj < end_time_obj:
                return False
