class CombinationCalculator:
    """
    This is a class that provides methods to calculate the number of combinations for a specific count, calculate all possible combinations, and generate combinations with a specified number of elements.
    """

    def __init__(self, datas: List[str]):
        """
        Initialize the calculator with a list of data.
        """
        self.datas = datas

    @staticmethod
    def count(n: int, m: int) -> int:
        """
        Calculate the number of combinations for a specific count.
        :param n: The total number of elements,int.
        :param m: The number of elements in each combination,int.
        :return: The number of combinations,int.
        """
        if m > n:
            return math.inf
        if m == 0:
            return 1
        return math.comb(n, m)

    @staticmethod
    def count_all(n: int) -> int:
        """
        Calculate the number of all possible combinations.
        :param n: The total number of elements,int.
        :return: The number of all possible combinations,int,if the number of combinations is greater than 2^63-1,return float("inf").
        """
        if n == 0:
            return 1
        if n == 1:
            return 2
        if n == 2:
            return 4
        if n == 3:
            return 8
        if n == 4:
            return 16
        if n == 5:
            return 32
        if n == 6:
            return 64
        if n == 7:
            return 128
        if n == 8:
            return 256
        if n == 9:
            return 512
        if n == 10:
            return 1024
        if n == 11:
            return 2048
        if n == 12:
            return 4096
        if n == 13:
            return 8192
        if n == 14:
            return 16384
        if n == 15:
            return 32768
        if n == 16:
            return 65536
        if n == 17:
            return 131072
        if n == 18:
            return 262144
        if n == 19:
            return 524288
        if n == 20:
            return 1048576
        return 2**n

    def select(self, m: int) -> List[List[str]]:
        """
        Generate combinations with a specified number of elements.
        :param m: The number of elements in each combination,int.
        :return: A list of combinations,List[List[str]].
        """
        if m > len(self.datas):
            return []
        if m == 0:
            return [[]]
        if m == 1:
            return [[data] for data in self.datas]
        result = []
        for i in range(len(self.datas)):
            result.extend([[data] + comb for data in self.datas[i+1:] for comb in self.select(m-1)])
        return result

    def select_all(self) -> List[List[str]]:
        """
        Generate all possible combinations of  selecting elements from the given data list,and it uses the select method.
        :return: A list of combinations,List[List[str]].
        """
        result = []
        for i in range(len(self.datas)):
            result.extend([[data] + comb for data in self.datas[i+1:] for comb in self.select_all()])
        return result
