        :param encrypted_text: The ciphertext to decipher,str.
        :param rails: The number of rails to use for decryption,int.
        :return: The deciphered plaintext,str.
        """
        rail_matrix = [['' for _ in range(rails)] for _ in range(len(encrypted_text))]
        row, col = 0, 0
        direction = 1

        for char in encrypted_text:
            rail_matrix[row][col] = char
            if direction == 1 and col < rails - 1:
                col += 1
            elif direction == 1 and col == rails - 1:
                row += 1
                direction = -1
            elif direction == -1 and col > 0:
                col -= 1
            elif direction == -1 and col == 0:
                row -= 1
                direction = 1

        plaintext = ''
        for i in range(rails):
            for j in range(len(encrypted_text)):
                if rail_matrix[i][j] != '':
                    plaintext += rail_matrix[i][j]

        return plaintext
