from collections import deque

class EightPuzzle:
    def __init__(self, initial_state):
        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]
        self.open_list = deque([initial_state])

    def find_blank(self, state):
        return state.index(0)

    def move(self, state, direction):
        blank_index = self.find_blank(state)
        if direction == 'up':
            new_state = state[:]
            new_state[blank_index // 3][blank_index % 3] = state[blank_index // 3][blank_index % 3 - 1]
            new_state[blank_index // 3][blank_index % 3 - 1] = 0
        elif direction == 'down':
            new_state = state[:]
            new_state[blank_index // 3][blank_index % 3] = state[blank_index // 3][blank_index % 3 + 1]
            new_state[blank_index // 3][blank_index % 3 + 1] = 0
        elif direction == 'left':
            new_state = state[:]
            new_state[blank_index // 3][blank_index % 3] = state[blank_index // 3 - 1][blank_index % 3]
            new_state[blank_index // 3 - 1][blank_index % 3] = 0
        elif direction == 'right':
            new_state = state[:]
            new_state[blank_index // 3][blank_index % 3] = state[blank_index // 3 + 1][blank_index % 3]
            new_state[blank_index // 3 + 1][blank_index % 3] = 0
        return new_state

    def get_possible_moves(self, state):
        blank_index = self.find_blank(state)
        possible_moves = []
        if blank_index // 3 > 0:
            possible_moves.append('up')
        if blank_index // 3 < 2:
            possible_moves.append('down')
        if blank_index % 3 > 0:
            possible_moves.append('left')
        if blank_index % 3 < 2:
            possible_moves.append('right')
        return possible_moves

    def solve(self):
        while self.open_list:
            current_state = self.open_list.popleft()
            if current_state == self.goal_state:
                return self.get_path(current_state)
            for direction in self.get_possible_moves(current_state):
                new_state = self.move(current_state, direction)
                if new_state not in self.open_list:
                    self.open_list.append(new_state)
        return None

    def get_path(self, state):
        path = []
        while state != self.initial_state:
            path.append(self.get_move_from_state(state, self.initial_state))
            state = self.move(self.initial_state, self.get_move_from_state(state, self.initial_state))
        return path[::-1]

    def get_move_from_state(self, current_state, state):
        for i in range(3):
            for j in range(3):
                if current_state[i][j] == state[i][j]:
                    return 'up' if i > 0 else 'down' if i < 2 else 'left' if j > 0 else 'right'
