        return state.index(0)

    def move(self, state, direction):
        i, j = self.find_blank(state)
        if direction == 'up' and i > 0:
            new_state = [row[:] for row in state]
            new_state[i][j], new_state[i-1][j] = new_state[i-1][j], new_state[i][j]
            return new_state
        elif direction == 'down' and i < 2:
            new_state = [row[:] for row in state]
            new_state[i][j], new_state[i+1][j] = new_state[i+1][j], new_state[i][j]
            return new_state
        elif direction == 'left' and j > 0:
            new_state = [row[:] for row in state]
            new_state[i][j], new_state[i][j-1] = new_state[i][j-1], new_state[i][j]
            return new_state
        elif direction == 'right' and j < 2:
            new_state = [row[:] for row in state]
            new_state[i][j], new_state[i][j+1] = new_state[i][j+1], new_state[i][j]
            return new_state
        return state

    def get_possible_moves(self, state):
        i, j = self.find_blank(state)
        moves = []
        if i > 0:
            moves.append('up')
        if i < 2:
            moves.append('down')
        if j > 0:
            moves.append('left')
        if j < 2:
            moves.append('right')
        return moves

    def solve(self):
        open_list = deque([self.initial_state])
        closed_list = set()
        path = []

        while open_list:
            current_state = open_list.popleft()
            if tuple(map(tuple, current_state)) == tuple(map(tuple, self.goal_state)):
                path = []
                while current_state != self.initial_state:
                    path.append(self.get_possible_moves(current_state)[0])
                    current_state = self.move(current_state, self.get_possible_moves(current_state)[0])
                return list(reversed(path))

            if tuple(map(tuple, current_state)) not in closed_list:
                closed_list.add(tuple(map(tuple, current_state)))
                for move in self.get_possible_moves(current_state):
                    new_state = self.move(current_state, move)
                    open_list.append(new_state)

        return None
