class EncryptionUtils:
    def __init__(self, key):
        self.key = key

    def caesar_cipher(self, plaintext, shift):
        ciphertext = ''
        for i in range(len(plaintext)):
            char = plaintext[i]
            if char.isalpha():
                shifted_char = chr((ord(char.lower()) - ord('a') + shift) % 26 + ord('a'))
                ciphertext += shifted_char
            else:
                ciphertext += char
        return ciphertext

    def vigenere_cipher(self, plaintext):
        ciphertext = ''
        key_index = 0
        for i in range(len(plaintext)):
            char = plaintext[i]
            if char.isalpha():
                key_char = self.key[key_index % len(self.key)]
                shifted_char = chr((ord(char.lower()) - ord('a') + ord(key_char.lower()) - ord('a')) % 26 + ord('a'))
                ciphertext += shifted_char
                key_index += 1
            else:
                ciphertext += char
        return ciphertext

    def rail_fence_cipher(self, plain_text, rails):
        ciphertext = ''
        matrix = [['' for _ in range(rails)] for _ in range(len(plain_text))]
        direction = 1
        row, col = 0, 0

        for char in plain_text:
            matrix[row][col] = char
            if direction == 1:
                col += 1
                if col == rails - 1:
                    row += 1
                    direction = -1
            else:
                col -= 1
                if col == 0:
                    row += 1
                    direction = 1

        for row in range(rails):
            for col in range(len(plain_text)):
                if matrix[row][col]:
                    ciphertext += matrix[row][col]

        return ciphertext
