        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    def find_blank(self, state):
        for i in range(len(state)):
            for j in range(len(state[i])):
                if state[i][j] == 0:
                    return i, j

    def move(self, state, direction):
        blank_i, blank_j = self.find_blank(state)
        if direction == 'up':
            new_state = [row[:] for row in state]
            new_state[blank_i - 1][blank_j] = state[blank_i][blank_j]
            new_state[blank_i][blank_j] = state[blank_i - 1][blank_j]
        elif direction == 'down':
            new_state = [row[:] for row in state]
            new_state[blank_i + 1][blank_j] = state[blank_i][blank_j]
            new_state[blank_i][blank_j] = state[blank_i + 1][blank_j]
        elif direction == 'left':
            new_state = [row[:] for row in state]
            new_state[blank_i][blank_j - 1] = state[blank_i][blank_j]
            new_state[blank_i][blank_j] = state[blank_i][blank_j - 1]
        elif direction == 'right':
            new_state = [row[:] for row in state]
            new_state[blank_i][blank_j + 1] = state[blank_i][blank_j]
            new_state[blank_i][blank_j] = state[blank_i][blank_j + 1]
        return new_state

    def get_possible_moves(self, state):
        blank_i, blank_j = self.find_blank(state)
        possible_moves = []
        if blank_i > 0:
            possible_moves.append('up')
        if blank_i < 2:
            possible_moves.append('down')
        if blank_j > 0:
            possible_moves.append('left')
        if blank_j < 2:
            possible_moves.append('right')
        return possible_moves

    def solve(self):
        open_list = [self.initial_state]
        closed_list = []
        path = []
        while open_list:
            current_state = open_list.pop(0)
            if current_state == self.goal_state:
                return path
            if current_state not in closed_list:
                closed_list.append(current_state)
                possible_moves = self.get_possible_moves(current_state)
                for move in possible_moves:
                    new_state = self.move(current_state, move)
                    open_list.append(new_state)
                path.append(move)
