        blank_i, blank_j = self.find_blank(state)
        if direction == 'up':
            new_state = [row[:] for row in state]
            new_state[blank_i][blank_j], new_state[blank_i - 1][blank_j] = new_state[blank_i - 1][blank_j], new_state[blank_i][blank_j]
        elif direction == 'down':
            new_state = [row[:] for row in state]
            new_state[blank_i][blank_j], new_state[blank_i + 1][blank_j] = new_state[blank_i + 1][blank_j], new_state[blank_i][blank_j]
        elif direction == 'left':
            new_state = [row[:] for row in state]
            new_state[blank_i][blank_j], new_state[blank_i][blank_j - 1] = new_state[blank_i][blank_j - 1], new_state[blank_i][blank_j]
        elif direction == 'right':
            new_state = [row[:] for row in state]
            new_state[blank_i][blank_j], new_state[blank_i][blank_j + 1] = new_state[blank_i][blank_j + 1], new_state[blank_i][blank_j]
        return new_state

    def get_possible_moves(self, state):
        blank_i, blank_j = self.find_blank(state)
        moves = []
        if blank_i > 0:
            moves.append('up')
        if blank_i < 2:
            moves.append('down')
        if blank_j > 0:
            moves.append('left')
        if blank_j < 2:
            moves.append('right')
        return moves

    def solve(self):
        open_list = deque([self.initial_state])
        closed_list = set()
        path = []

        while open_list:
            current_state = open_list.popleft()
            if current_state == self.goal_state:
                while current_state != self.initial_state:
                    path.append(self.get_possible_moves(current_state)[0])
                    current_state = self.move(current_state, self.get_possible_moves(current_state)[0])
                return reversed(path)

            closed_list.add(tuple(map(tuple, current_state)))

            possible_moves = self.get_possible_moves(current_state)
            for move in possible_moves:
                next_state = self.move(current_state, move)
                if tuple(map(tuple, next_state)) not in closed_list:
                    open_list.append(next_state)

        return None
