        self.board_size = board_size
        self.board = [[' ' for _ in range(board_size)] for _ in range(board_size)]
        self.current_player = 'X'

    def make_move(self, row, col):
        if self.board[row][col] == ' ':
            self.board[row][col] = self.current_player
            self.current_player = 'O' if self.current_player == 'X' else 'X'
            return True
        else:
            return False

    def check_winner(self):
        for i in range(self.board_size):
            for j in range(self.board_size):
                if self._check_five_in_a_row(i, j, (0, 1)) or self._check_five_in_a_row(i, j, (1, 1)):
                    return self.current_player
        if self._check_five_in_a_row(-1, -1, (-1, -1)) or self._check_five_in_a_row(-1, -1, (1, -1)):
            return self.current_player
        if self._check_five_in_a_row(-1, 0, (-1, 0)) or self._check_five_in_a_row(-1, 0, (1, 0)):
            return self.current_player
        if self._check_five_in_a_row(0, -1, (-1, 1)) or self._check_five_in_a_row(0, -1, (1, 1)):
            return self.current_player
        return None

    def _check_five_in_a_row(self, row, col, direction):
        count = 0
        dx, dy = direction
        while 0 <= row < self.board_size and 0 <= col < self.board_size and self.board[row][col] == self.current_player:
            count += 1
            row += dx
            col += dy
        return count >= 5

